package com.yigongbao.backup.cold;
import com.yigongbao.backup.storage.local.LocalDirectoryArtifactStore; import org.junit.jupiter.api.Test; import java.nio.file.*; import java.util.*; import static org.assertj.core.api.Assertions.*;
class HotCleanupServiceTest { @Test void onlyVerifiedWholeBatchCanBeCleaned() throws Exception {Path root=Files.createTempDirectory("hot");var store=new LocalDirectoryArtifactStore(root);store.put("orders/a.zip",new java.io.ByteArrayInputStream(new byte[]{1}));var s=new HotCleanupService(store);assertThatThrownBy(()->s.cleanup("b")).isInstanceOf(IllegalStateException.class);s.registerVerified("b",List.of("orders/a.zip"));assertThat(s.cleanup("b").deleted()).isEqualTo(1);assertThat(root.resolve("orders/a.zip")).doesNotExist();assertThatThrownBy(()->s.cleanup("b")).isInstanceOf(IllegalStateException.class);}}
